3	import 'package:flutter/material.dart';
4	import 'package:flutter/semantics.dart';
5	
6	import '../../../../core/design_tokens.dart';
7	import '../../../../core/widgets/app_button.dart';
8	import '../../domain/repositories/vault_repository.dart';
9	import '../widgets/pin_keypad.dart';
10	
11	/// `/vault` — the epic's one lock screen, shown whenever
12	/// `VaultRepository.currentStatus` isn't `VaultStatus.unlocked`
13	/// (`core/navigation/app_router.dart`'s `_redirect`). Auto-triggers the OS
14	/// biometric prompt once in [initState]; a successful
15	/// [VaultRepository.authenticate] call flips `currentStatus` to `unlocked`,
16	/// which — via `statusStream`/`refreshListenable` — re-runs the redirect and
17	/// navigates away from here on its own, so this widget never navigates
18	/// imperatively itself.
19	///
20	/// Story 2.2: every biometric failure (decline/cancel/any OS lockout — the
21	/// generic `authenticate()` catches already cover it, spec-2-2) falls
22	/// through to a real [PinKeypad] + error band, never a second biometric
23	/// "Tentar novamente" affordance (AC2). The "Usar PIN" ghost link reaches
24	/// the same keypad directly, with no error band, before any biometric
25	/// failure has happened. [VaultRepository.submitPin]'s own success emits
26	/// `VaultStatus.unlocked`, same as [VaultRepository.authenticate] — this
27	/// widget navigates away on that exactly the same way, with no branch for
28	/// "which path unlocked it".
29	class VaultLockScreen extends StatefulWidget {
30	  const VaultLockScreen({
31	    required this.vaultRepository,
32	    required this.attemptBiometricFirst,
33	    super.key,
34	  });
35	
36	  final VaultRepository vaultRepository;
37	
38	  /// Story 2.4 — `AccountSettingsRepository.currentBiometricEnabled`, read
39	  /// by `core/navigation/app_router.dart`'s `/vault` builder. `true`
40	  /// (including the default before the boot fetch resolves, Design Notes)
41	  /// auto-triggers [VaultRepository.authenticate] in [initState] exactly
42	  /// as before this story; `false` skips straight to the PIN keypad — PIN
43	  /// remains the access method regardless (Boundaries).
44	  final bool attemptBiometricFirst;
45	
46	  @override
47	  State<VaultLockScreen> createState() => _VaultLockScreenState();
48	}
49	
50	class _VaultLockScreenState extends State<VaultLockScreen> {
51	  static const _biometricFailureMessage =
52	      'Não foi possível reconhecer — digite seu PIN';
53	
54	  /// No specific copy is given anywhere in `docs/input/` for a PIN
55	  /// mismatch (the I/O matrix only specifies the `Failure` returned) —
56	  /// decided here (Design Notes), mirroring the biometric failure band's
57	  /// own tone.
58	  static const _pinMismatchMessage = 'PIN incorreto. Tente novamente.';
59	
60	  /// No specific copy is given anywhere in `docs/input/` for a
61	  /// `submitPin` call that never resolves (decided here, Design Notes) —
62	  /// review finding: without a bound, a hung secure-storage channel call
63	  /// would leave [_submittingPin] stuck `true` forever, permanently
64	  /// blocking every future attempt and contradicting the spec's own
65	  /// "never a dead end" boundary.
66	  static const _submitTimeoutMessage =
67	      'Não foi possível verificar o PIN. Tente novamente.';
68	
69	  static const _submitPinTimeout = Duration(seconds: 10);
70	
71	  bool _showPinKeypad = false;
72	  String? _errorMessage;
73	
74	  /// Re-entrancy guard for [_submitPin], also passed to [PinKeypad] as
75	  /// `enabled: !_submittingPin` — [PinKeypad] clears its own buffer and
76	  /// accepts new taps immediately after calling `onSubmit`, before the
77	  /// awaited [VaultRepository.submitPin] below resolves, so a fast second
78	  /// 4-digit entry could otherwise be accepted and then silently dropped
79	  /// here with no feedback; gating the keypad itself means it's never
80	  /// accepted in the first place.
81	  bool _submittingPin = false;
82	
83	  @override
84	  void initState() {
85	    super.initState();
86	    if (widget.attemptBiometricFirst) {
87	      _attemptAuthenticate();
88	    } else {
89	      // Story 2.4 — the preference is already `false` by the time this
90	      // screen builds: skip the OS biometric prompt entirely and show the
91	      // PIN keypad directly, with no error band (same "pre-failure" look
92	      // as tapping "Usar PIN" manually).
93	      _showPinKeypad = true;
94	    }
95	  }
96	
97	  Future<void> _attemptAuthenticate() async {
98	    final result = await widget.vaultRepository.authenticate();
99	    if (!mounted) {
100	      return;
101	    }
102	
103	    // On success, `currentStatus` is already `unlocked` and the router's
104	    // own `refreshListenable` will navigate away from `/vault` on its own —
105	    // this widget has nothing further to do (and may already be in the
106	    // process of being disposed by the time that happens).
107	    var shouldAnnounceFailure = false;
108	    result.match(
109	      (_) {
110	        // If the user already reached the keypad manually (via "Usar
111	        // PIN") before this pending call resolved, this late failure must
112	        // never clobber whatever the keypad is currently showing — AC2's
113	        // "no second biometric-retry affordance" only concerns the
114	        // biometric view itself, which is no longer on screen.
115	        final alreadyOnKeypad = _showPinKeypad;
116	        shouldAnnounceFailure = !alreadyOnKeypad;
117	        if (!alreadyOnKeypad) {
118	          setState(() {
119	            _showPinKeypad = true;
120	            _errorMessage = _biometricFailureMessage;
121	          });
122	        }
123	      },
124	      (_) {},
125	    );
126	
127	    // `sendAnnouncement()` (see `_announce` below) is honored on both
128	    // Android and iOS — this app is iOS-only, where VoiceOver doesn't
129	    // reliably treat a live-region subtree update as an announcement on
130	    // its own, so the biometric->PIN transition is spoken explicitly
131	    // here rather than relying on any ambient live region.
132	    if (shouldAnnounceFailure && mounted) {
133	      await _announce(_biometricFailureMessage);
134	    }
135	  }
136	
137	  void _useManualPin() {
138	    setState(() {
139	      _showPinKeypad = true;
140	      _errorMessage = null;
141	    });
142	  }
143	
144	  @override
145	  void didUpdateWidget(covariant VaultLockScreen oldWidget) {
146	    super.didUpdateWidget(oldWidget);
147	    // Review finding: `attemptBiometricFirst` was only ever consulted
148	    // once, in `initState` — defensive future-proofing in case this
149	    // already-mounted widget is ever rebuilt with a new value (today,
150	    // nothing actually does: `app_router.dart` reads `currentBiometricEnabled`
151	    // fresh only when `/vault` is newly built, not while already resident
152	    // there — see its own doc comment). If that ever changes, e.g. a boot-
153	    // time `fetchBiometricEnabled()` resolving to `false` while `/vault` is
154	    // already mounted (with the default `true`) and already auto-triggered
155	    // the OS biometric prompt: that in-flight prompt can't be retracted
156	    // from here, but the preference can still be honored going forward: if
157	    // we're still waiting on it (haven't fallen through to the keypad yet),
158	    // switch to it proactively — exactly as if the user had tapped "Usar
159	    // PIN" themselves. A `false` -> `true` change is deliberately left
160	    // alone: re-triggering biometric out from under a user who's already
161	    // on the keypad (whether because it failed or because they chose "Usar
162	    // PIN") would be a surprise, not a fix, and PIN remains the access
163	    // method regardless either way (Boundaries).
164	    if (oldWidget.attemptBiometricFirst &&
165	        !widget.attemptBiometricFirst &&
166	        !_showPinKeypad) {
167	      _useManualPin();
168	    }
169	  }
170	
171	  Future<void> _submitPin(String pin) async {
172	    if (_submittingPin) {
173	      return;
174	    }
175	    // Review finding: previously left in place, a stale mismatch/timeout
176	    // message from a prior attempt lingered unchanged through this new
177	    // attempt, with nothing distinguishing "old error, nothing happening"
178	    // from "new attempt in flight" — cleared here so only this attempt's
179	    // own outcome (or the keypad's disabled/dimmed state) is visible.
180	    setState(() {
181	      _submittingPin = true;
182	      _errorMessage = null;
183	    });
184	    try {
185	      final result = await widget.vaultRepository
186	          .submitPin(pin)
187	          .timeout(_submitPinTimeout);
188	      if (!mounted) {
189	        return;
190	      }
191	      if (result.isLeft()) {
192	        // Mismatch: stays locked, no attempt cap — the keypad itself has
193	        // already cleared its own buffer by the time this runs
194	        // (PinKeypad's own contract), so the user can simply try again.
195	        setState(() => _errorMessage = _pinMismatchMessage);
196	        await _announce(_pinMismatchMessage);
197	      }
198	      // On a match (first-use or later), `currentStatus` is already
199	      // `unlocked` and the router navigates away on its own, same as a
200	      // successful `authenticate()`.
201	    } on TimeoutException {
202	      if (!mounted) {
203	        return;
204	      }
205	      // Bounds the wait so a hung secure-storage call can never leave
206	      // `_submittingPin` stuck `true` forever — the `finally` below still
207	      // runs because this `await` has now actually completed (with a
208	      // thrown `TimeoutException`), same retryable outcome as a mismatch.
209	      setState(() => _errorMessage = _submitTimeoutMessage);
210	      await _announce(_submitTimeoutMessage);
211	    } finally {
212	      if (mounted) {
213	        setState(() => _submittingPin = false);
214	      } else {
215	        _submittingPin = false;
216	      }
217	    }
218	  }
219	
220	  Future<void> _announce(String message) async {
221	    if (!mounted) {
222	      return;
223	    }
224	    await SemanticsService.sendAnnouncement(
225	      View.of(context),
226	      message,
227	      TextDirection.ltr,
228	    );
229	  }
230	
231	  @override
232	  Widget build(BuildContext context) {
233	    // No ambient `Semantics(liveRegion: true)` wrapper here — it would
234	    // re-trigger on every single digit tap inside `PinKeypad` (its own
235	    // `_ProgressDots` label changes each tap), not just the two
236	    // transitions that actually need announcing. Those two (biometric
237	    // failure, PIN mismatch) are already covered explicitly and reliably
238	    // by `_announce()` below.
239	    //
240	    // Tela 0.1b/c (the PIN keypad) is top-aligned under its own
241	    // `pinScreenPadding`, unlike Tela 0.1 (biometric), which stays
242	    // centered under the generic `screenPadding` — matching each state's
243	    // own layout in `cerne-prototype.html` (Story 2.2 correction).
244	    return Scaffold(
245	      backgroundColor: DesignTokens.colorSurfaceBg,
246	      body: _showPinKeypad
247	          ? Padding(
248	              padding: DesignTokens.pinScreenPadding,
249	              child: Align(
250	                alignment: Alignment.topCenter,
251	                child: _PinView(
252	                  errorMessage: _errorMessage,
253	                  onSubmit: _submitPin,
254	                  enabled: !_submittingPin,
255	                ),
256	              ),
257	            )
258	          : Center(
259	              child: Padding(
260	                padding: DesignTokens.screenPadding,
261	                child: _BiometricView(onUsePin: _useManualPin),
262	              ),
263	            ),
264	    );
265	  }
266	}
267	
268	class _BiometricView extends StatelessWidget {
269	  const _BiometricView({required this.onUsePin});
270	
271	  final VoidCallback onUsePin;
272	
273	  @override
274	  Widget build(BuildContext context) {
275	    return Column(
276	      mainAxisSize: MainAxisSize.min,
277	      children: [
278	        const Icon(
279	          Icons.lock_outline,
280	          size: DesignTokens.spacing2xl,
281	          color: DesignTokens.colorTextSecondary,
282	        ),
283	        const SizedBox(height: DesignTokens.spacingMd),
284	        Text(
285	          'Cerne bloqueado',
286	          textAlign: TextAlign.center,
287	          style: DesignTokens.textHeadlineMd.copyWith(
288	            color: DesignTokens.colorTextPrimary,
289	          ),
290	        ),
291	        const SizedBox(height: DesignTokens.spacingSm),
292	        Text(
293	          'Use a biometria do seu dispositivo para continuar.',
294	          textAlign: TextAlign.center,
295	          style: DesignTokens.textBodyMd.copyWith(
296	            color: DesignTokens.colorTextSecondary,
297	          ),
298	        ),
299	        const SizedBox(height: DesignTokens.spacingLg),
300	        AppButton(
301	          variant: AppButtonVariant.textGhost,
302	          label: 'Usar PIN',
303	          onPressed: onUsePin,
304	        ),
305	      ],
306	    );
307	  }
308	}
309	
